    if (2n * rem > scaled.d || (2n * rem === scaled.d && k % 2n)) k++;
    const value = qmul(q(sign * k), unit);
    if (qcmp(q(sign * value.n, value.d), power(maxExponent + 1)) >= 0) return fail();
    return { status: 'success', value };
