    // this does not test decay at infinity or prove the Schwartz assertion.
    const degree = 24;
    const factorial = [1n];
    for (let k = 1; k <= degree; k++) factorial[k] = factorial[k - 1] * BigInt(k);
    const scale = factorial[degree];
