    const nSign = (x) => {
      const a = x.a, b = x.b;
      if (a.n >= 0n && b.n >= 0n) return a.n > 0n || b.n > 0n ? 1 : 0;
      if (a.n <= 0n && b.n <= 0n) return a.n < 0n || b.n < 0n ? -1 : 0;
      const c = fSign(fSub(fMul(a, a), fMul(three, fMul(b, b))));
      return a.n > 0n ? c : -c;
    };
